import{_ as i,o as n,c as t,a3 as r}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"UGSo Special","description":"Animierte SVG-Linien und Summenknoten für ioBroker VIS 2.","frontmatter":{"title":"UGSo Special","description":"Animierte SVG-Linien und Summenknoten für ioBroker VIS 2."},"headers":[],"relativePath":"iobroker/widgets/ugso-spezial/index.md","filePath":"iobroker/widgets/ugso-spezial/index.md","lastUpdated":1794653853000}'),a={name:"iobroker/widgets/ugso-spezial/index.md"};function s(o,e,l,d,u,g){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="ugso-special" tabindex="-1">UGSo Special <a class="header-anchor" href="#ugso-special" aria-label="Permalink to &quot;UGSo Special&quot;">​</a></h1><p>Mit <strong>UGSo Special</strong> stellst du Datenflüsse in VIS 2 dar, zum Beispiel die Leistung mehrerer Verbraucher. Das Widget-Set enthält zwei Bausteine.</p><h2 id="widgets" tabindex="-1">Widgets <a class="header-anchor" href="#widgets" aria-label="Permalink to &quot;Widgets&quot;">​</a></h2><ul><li><strong>SVG-Line</strong> verbindet Punkte gerade, rechtwinklig oder über Zwischenpunkte. Farben, Strichlängen und Pfeilspitzen sind einstellbar. Positive Werte animieren vorwärts, negative rückwärts; bei null stoppt die Animation. Die Geschwindigkeit kann fest oder vom Betrag des Werts abhängig sein.</li><li><strong>SVG LineBox</strong> addiert bis zu vier Eingangsleitungen und einen optionalen Korrekturwert. Die Summe kann an bis zu zwei Ausgangsleitungen weitergegeben oder in der Laufzeitansicht in einen vorhandenen beschreibbaren numerischen Datenpunkt unter <code>0_userdata.0</code> geschrieben werden. Fehlt der Wert eines ausgewählten Eingangs, wartet die Box auf diesen Wert.</li></ul><p>Im Editor rasten gelbe Endpunkte beim Ziehen an einer anderen Linie oder LineBox ein. Ein Ende mit Pfeilspitze kann nicht andocken. Das Andocken richtet die Grafik aus; die Werteverbindungen stellst du separat in der LineBox ein.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><h3 id="katalogvorbereitung-0-1-34" tabindex="-1">Katalogvorbereitung 0.1.34 <a class="header-anchor" href="#katalogvorbereitung-0-1-34" aria-label="Permalink to &quot;Katalogvorbereitung 0.1.34&quot;">​</a></h3><p>Die Veröffentlichung enthält vollständige Release-Hinweise in allen elf Katalogsprachen, korrigierte Paketabhängigkeiten sowie automatisches Linting und ioBroker-Paketprüfungen. Die Veröffentlichung erfolgt mit npm-Herkunftsnachweis über GitHub Actions. bluefox ist als npm-Mitinhaber eingetragen. Die Aufnahme in den offiziellen Katalog ist weiterhin beantragt; Widget-Funktionen und vorhandene Projekte bleiben erhalten.</p><p>Der technische Paketname lautet jetzt <code>iobroker.vis-2-widgets-ugso-special</code>. Exportiere vorhandene VIS-2-Projekte als Sicherung, installiere das neue Paket und starte VIS 2 neu. Prüfe die Projekte vor dem Entfernen des bisherigen Pakets. Die Widget-Template-IDs und der interne Federationsname bleiben erhalten.</p><p>Voraussetzung ist eine laufende VIS-2-Installation. Installiere das Widget-Set über die GitHub-URL des Projekts in ioBroker Admin (Expertenmodus). Starte VIS 2 nach Updates neu, damit die neue Version geladen wird. Im Editor findest du beide Widgets in der Palette unter <strong>UGSo Special</strong>.</p><ul><li><a href="https://github.com/rockbaer2007/ioBroker.vis-2-widgets-ugso-special" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://github.com/rockbaer2007/ioBroker.vis-2-widgets-ugso-special/releases" target="_blank" rel="noreferrer">Releases</a></li><li><a href="https://www.npmjs.com/package/iobroker.vis-2-widgets-ugso-special" target="_blank" rel="noreferrer">npm</a></li></ul>',11)])])}const p=i(a,[["render",s]]);export{h as __pageData,p as default};
